// --- CONFIGURATION ---
u_min := 0;
u_max := 3.14159; // PI: the 3 petals traced ONCE (with 2*PI the curve is
                  // traced twice and the branches become tangent)
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- SHADER CODE ---
// NB: do not declare variables named PI, pi, tau: the translator
// replaces them with the numeric value throughout the script.

// Geometric parameters
float a = 3.0;  // Trefoil amplitude
float r = 0.2;  // Tube radius (0.2 < min curvature radius 0.3:
                // the single petal does not self-intersect)

// Curve: 3-petal polar rose rho = a*cos(3*theta) in the z=0 plane,
// with u in [0, PI]. It passes through the origin THREE times (u = PI/6, PI/2,
// 5*PI/6): the three petals cross at the center. Unlike the
// four-leaf clover, here the crossings are TRANSVERSAL (the three tangents at
// the origin are at 30, 90, 150 degrees, all different), not tangent:
// so the cutout is clean and well defined.
float c3u = cos(3.0 * u);
float s3u = sin(3.0 * u);
vec3 Curve = vec3(a * c3u * cos(u), a * c3u * sin(u), 0.0);

// --- FIRST DERIVATIVE (analytic velocity) ---
vec3 dC = vec3(
    a * (-3.0 * s3u * cos(u) - c3u * sin(u)),
    a * (-3.0 * s3u * sin(u) + c3u * cos(u)),
    0.0
);

vec3 Tangent = normalize(dC);

// --- STABLE FRAME COMPUTATION ---
// The curve lies in the z=0 plane: the tangent is never parallel
// to Z, so the frame never degenerates.
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = normalize(cross(Tangent, Up));
vec3 Norm = normalize(cross(Binorm, Tangent));

// --- TUBE CONSTRUCTION ---
vec3 pos = Curve + r * (cos(v) * Norm + sin(v) * Binorm);

// Return the point in 4D (X, Y, Z, P)
return vec4(pos * 0.35, 0.0);

//CUTOUT_BEGIN
// Cut of the inner walls in the crossing zone (origin).
// Scheme from the Self-Intersecting Tube (PRECISE distance: coarse scan
// + 5 Newton steps, the raw steps estimate the minimum with error
// ~1e-2 and leave z-fight patches along the seam).
// The nodes here are THREE (u_k = PI/6 + k*PI/3): for a fragment near
// node k, the branches of the other TWO nodes are checked. Its own
// branch cannot touch itself (verified: stays at distance >= 0.48 with
// r = 0.2), so it is skipped.
float a2 = 3.0;
float r2 = 0.2;
float PI_2 = 3.14159265359;
float NODE0 = PI_2 / 6.0;      // 0.5236
float NSTEP = PI_2 / 3.0;      // 1.0472

// node closest to the fragment
float kNear = floor((u - NODE0) / NSTEP + 0.5);
float uNode = NODE0 + kNear * NSTEP;

float activateWindow = 0.5;
bool didCut = false;

if (abs(u - uNode) < activateWindow) {
    float c3f = cos(3.0 * u);
    float s3f = sin(3.0 * u);
    vec3 Curve2 = vec3(a2 * c3f * cos(u), a2 * c3f * sin(u), 0.0);
    vec3 dC2 = vec3(
        a2 * (-3.0 * s3f * cos(u) - c3f * sin(u)),
        a2 * (-3.0 * s3f * sin(u) + c3f * cos(u)),
        0.0
    );
    vec3 Tangent2 = normalize(dC2);
    vec3 Up2 = vec3(0.0, 0.0, 1.0);
    vec3 Binorm2 = normalize(cross(Tangent2, Up2));
    vec3 Norm2 = normalize(cross(Binorm2, Tangent2));
    vec3 pos2 = Curve2 + r2 * (cos(v) * Norm2 + sin(v) * Binorm2);

    float bestDist = 1000.0;

    for (float j = 0.0; j < 3.0; j = j + 1.0) {
        float node = NODE0 + j * NSTEP;
        // skip the fragment's node
        if (abs(node - uNode) < 0.1) { continue; }

        // 1. coarse scan around the node
        float bestU = node;
        float bestD = 1000.0;
        for (float k = 0.0; k < 16.0; k = k + 1.0) {
            float u2 = node - 0.4 + 0.8 * (k / 15.0);
            float cc = cos(3.0 * u2);
            vec3 c2 = vec3(a2 * cc * cos(u2), a2 * cc * sin(u2), 0.0);
            float d = length(pos2 - c2);
            if (d < bestD) { bestD = d; bestU = u2; }
        }

        // 2. Newton on g(u2) = dot(pos2 - C(u2), C'(u2)) = 0
        float uN = bestU;
        for (float it = 0.0; it < 5.0; it = it + 1.0) {
            float cN3 = cos(3.0 * uN);
            float sN3 = sin(3.0 * uN);
            float cN1 = cos(uN);
            float sN1 = sin(uN);
            vec3 cN = vec3(a2 * cN3 * cN1, a2 * cN3 * sN1, 0.0);
            vec3 t1 = vec3(a2 * (-3.0 * sN3 * cN1 - cN3 * sN1),
                           a2 * (-3.0 * sN3 * sN1 + cN3 * cN1), 0.0);
            vec3 t2 = vec3(a2 * (-9.0 * cN3 * cN1 + 6.0 * sN3 * sN1 - cN3 * cN1),
                           a2 * (-9.0 * cN3 * sN1 - 6.0 * sN3 * cN1 - cN3 * sN1), 0.0);
            vec3 w = pos2 - cN;
            float g = dot(w, t1);
            float gp = dot(w, t2) - dot(t1, t1);
            if (abs(gp) > 0.000001) { uN = uN - g / gp; }
            uN = clamp(uN, node - 0.45, node + 0.45);
        }
        float cB3 = cos(3.0 * uN);
        vec3 cB = vec3(a2 * cB3 * cos(uN), a2 * cB3 * sin(uN), 0.0);
        bestDist = min(bestDist, min(bestD, length(pos2 - cB)));
    }

    didCut = (bestDist < r2);
}

return didCut;
//CUTOUT_END
